import React from "react";
import {
  AbsoluteFill,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
  Easing,
} from '../remotionShim';
// Load closest approximations for requested fonts: Jost
import { makeLoadFont } from '../googleFonts';
const loadJost = makeLoadFont('Jost');

const { fontFamily: jostFamily } = loadJost();



export type BalmToPowderProps = Record<string, any>;

// Approximate character widths in 'em' for geometric sans-serif fonts like Jost
// Adjusted wider to perfectly space characters out and avoid overlap, especially for the periods.
const charWidths: Record<string, number> = {
  T: 0.65,
  A: 0.75,
  I: 0.45,
  L: 0.65,
  O: 0.8,
  R: 0.75,
  ".": 0.5, // Significantly increased to give the acronym characters breathing room
  U: 0.75,
  C: 0.75,
  H: 0.8,
  D: 0.8,
  E: 0.7,
  S: 0.7,
  N: 0.8,
  P: 0.7,
  K: 0.7,
  Y: 0.7,
  " ": 0.5,
};

type CharLayout = {
  char: string;
  pos: number; // offset from exact center in em units
  w: number;
};

function getWordLayout(word: string): CharLayout[] {
  let totalWidth = 0;
  const chars = word.split("");
  const layout = chars.map((char) => {
    // Default to a generous width for undefined characters to prevent squishing
    const w = charWidths[char.toUpperCase()] || 0.75;
    const pos = totalWidth + w / 2;
    totalWidth += w;
    return { char, pos, w };
  });
  // Shift all positions so the entire string is centered around 0
  return layout.map((l) => ({
    ...l,
    pos: l.pos - totalWidth / 2,
  }));
}

const BalmToPowderAnimation: React.FC<BalmToPowderProps> = ({
  backgroundColor = "#FFFFFF",
  textColor = "#000000",
  subtitle = "SIGNATURE SELLING AND SERVICE SYSTEM",
  acronyms = [
    { letter: "T", word: "TOUCH" },
    { letter: "A", word: "ADDRESS" },
    { letter: "I", word: "INITIATE" },
    { letter: "L", word: "LINK" },
    { letter: "O", word: "OPPORTUNITY" },
    { letter: "R", word: "RETAIN" },
  ],
  durationInSeconds = 30,
}) => {
  const frame = useCurrentFrame();
  const { height, durationInFrames } = useVideoConfig();

  // Em size relative to screen height for perfectly responsive typography
  const em = height * 0.22;

  if (!acronyms || acronyms.length === 0) {
    return <AbsoluteFill style={{ backgroundColor }} />;
  }

  // Safely construct the base word from the acronyms array (e.g., T.A.I.L.O.R.)
  const baseWord = acronyms.map((a) => (a.letter || " ").charAt(0)).join(".");
  const baseLayout = getWordLayout(baseWord);

  // Calculate the exact visual width of the base acronym word from the left edge of the first char to right edge of last
  const totalBaseWidth =
    baseLayout.length > 0
      ? baseLayout[baseLayout.length - 1].pos +
        baseLayout[baseLayout.length - 1].w / 2 -
        (baseLayout[0].pos - baseLayout[0].w / 2)
      : 0;

  const TARGETS = acronyms.map((acronym, i) => ({
    word: acronym.word || " ",
    baseIndex: i * 2, // Maps directly to the index in baseLayout skipping the periods
  }));

  // Divide the total duration into evenly sized parts
  const totalParts = acronyms.length + 1.5;
  const cycleDuration = durationInFrames / totalParts;

  const INTRO_FRAMES = cycleDuration;
  const CYCLE_FRAMES = cycleDuration;
  const OUTRO_FRAMES = cycleDuration * 0.5;

  const cycleIndex = Math.floor((frame - INTRO_FRAMES) / CYCLE_FRAMES);
  const isIntro = frame < INTRO_FRAMES;
  const isOutro = frame >= INTRO_FRAMES + acronyms.length * CYCLE_FRAMES;
  const activeCycleIndex = Math.max(
    0,
    Math.min(acronyms.length - 1, cycleIndex)
  );

  const activeTarget = TARGETS[activeCycleIndex];
  const targetLayout = getWordLayout(activeTarget.word);

  const localFrame = isIntro
    ? 0
    : isOutro
    ? CYCLE_FRAMES
    : frame - (INTRO_FRAMES + activeCycleIndex * CYCLE_FRAMES);

  // Define relative keyframe points within each cycle for smooth transitions
  const t1 = CYCLE_FRAMES * (15 / 120);
  const t2 = CYCLE_FRAMES * (45 / 120);
  const t3 = CYCLE_FRAMES * (85 / 120);
  const t4 = CYCLE_FRAMES * (115 / 120);

  // Intro specific opacities
  const baseWordIntroOpacity = interpolate(
    frame,
    [0, INTRO_FRAMES * 0.25],
    [0, 1],
    { extrapolateRight: "clamp" }
  );

  const subtitleOpacity = interpolate(
    frame,
    [
      INTRO_FRAMES * 0.25,
      INTRO_FRAMES * 0.35,
      INTRO_FRAMES * 0.75,
      INTRO_FRAMES * 0.85,
    ],
    [0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Outro specific opacities
  const baseWordOutroOpacity = interpolate(
    frame - (INTRO_FRAMES + acronyms.length * CYCLE_FRAMES),
    [OUTRO_FRAMES * 0.5, OUTRO_FRAMES],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Cycle specific dynamic opacities and movement
  const nonTargetOpacity = isIntro
    ? baseWordIntroOpacity
    : isOutro
    ? baseWordOutroOpacity
    : interpolate(
        localFrame,
        [0, t1, t4 - CYCLE_FRAMES * (10 / 120), CYCLE_FRAMES],
        [1, 0, 0, 1],
        { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
      );

  const targetLetterX =
    isIntro || isOutro
      ? baseLayout[activeTarget.baseIndex].pos
      : interpolate(
          localFrame,
          [t1, t2, t3, t4],
          [
            baseLayout[activeTarget.baseIndex].pos,
            targetLayout[0].pos,
            targetLayout[0].pos,
            baseLayout[activeTarget.baseIndex].pos,
          ],
          {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.inOut(Easing.cubic),
          }
        );

  const suffixOpacity =
    isIntro || isOutro
      ? 0
      : interpolate(
          localFrame,
          [t1, t1 + (t2 - t1) * 0.8, t3 + (t4 - t3) * 0.2, t4],
          [0, 1, 1, 0],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );

  return (
    <AbsoluteFill style={{ overflow: "hidden", backgroundColor }}>
      <div style={{ position: "absolute", left: "50%", top: "50%" }}>
        {/* Subtitle element visible only during Intro phase */}
        <div
          style={{
            position: "absolute",
            left: 0,
            top: em * 0.7,
            transform: "translate(-50%, 0)",
            opacity: isIntro ? subtitleOpacity : 0,
            width: totalBaseWidth * em,
            display: "flex",
            justifyContent: subtitle.split(" ").length > 1 ? "space-between" : "center",
            whiteSpace: "nowrap",
            transition: "none",
          }}
        >
          {subtitle.split(" ").map((word, i, arr) => (
            <span
              key={`sub-${i}`}
              style={{
                fontSize: em * 0.15,
                fontFamily: jostFamily,
                fontWeight: 300,
                color: textColor,
                textTransform: "uppercase",
                letterSpacing: "0.05em",
                marginRight: i === arr.length - 1 ? "-0.05em" : 0,
              }}
            >
              {word}
            </span>
          ))}
        </div>

        {/* Base letters (e.g. T.A.I.L.O.R.) */}
        {baseLayout.map((letter, i) => {
          const isTarget = i === activeTarget.baseIndex && !isIntro && !isOutro;

          let opacity = 1;
          let x = letter.pos;

          if (isTarget) {
            opacity = isIntro
              ? baseWordIntroOpacity
              : isOutro
              ? baseWordOutroOpacity
              : 1;
            x = targetLetterX;
          } else {
            opacity = nonTargetOpacity;
          }

          return (
            <div
              key={`base-${i}`}
              style={{
                position: "absolute",
                left: x * em,
                top: 0,
                transform: "translate(-50%, -50%)",
                opacity,
                fontSize: em,
                fontFamily: jostFamily,
                fontWeight: 200,
                color: textColor,
                textTransform: "uppercase",
                transition: "none",
              }}
            >
              {letter.char}
            </div>
          );
        })}

        {/* Dynamic Suffix Letters for the currently spelling target word */}
        {!isIntro &&
          !isOutro &&
          targetLayout.slice(1).map((letter, i) => {
            return (
              <div
                key={`suffix-${i}`}
                style={{
                  position: "absolute",
                  left: letter.pos * em,
                  top: 0,
                  transform: "translate(-50%, -50%)",
                  opacity: suffixOpacity,
                  fontSize: em,
                  fontFamily: jostFamily,
                  fontWeight: 200,
                  color: textColor,
                  textTransform: "uppercase",
                  transition: "none",
                }}
              >
                {letter.char}
              </div>
            );
          })}
      </div>
    </AbsoluteFill>
  );
};

export default BalmToPowderAnimation;